using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration including feature flags and limits.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "production",
            MaxRequestsPerMinute = 100,
            Features = new
            {
                DarkMode = true,
                BetaAccess = false,
                MaintenanceMode = false
            },
            SupportedRegions = new[] { "us-east-1", "eu-west-1", "ap-southeast-1" }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Check whether a specific feature flag is enabled.")]
    public static string CheckFeatureFlag(
        [Description("Name of the feature flag to check (e.g., DarkMode, BetaAccess)")] string flagName)
    {
        var flags = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase)
        {
            ["DarkMode"] = true,
            ["BetaAccess"] = false,
            ["MaintenanceMode"] = false
        };

        if (flags.TryGetValue(flagName, out var enabled))
            return $"Feature '{flagName}' is {(enabled ? "enabled" : "disabled")}.";

        return $"Feature '{flagName}' not found. Available flags: {string.Join(", ", flags.Keys)}";
    }

    [McpServerTool, Description("Get the list of supported deployment regions.")]
    public static string GetRegions()
    {
        var regions = new[] { "us-east-1", "eu-west-1", "ap-southeast-1" };
        return $"Supported regions: {string.Join(", ", regions)}";
    }
}

